"granddaughter": ["Grandma loves her granddaughter.", "奶奶很愛她的孫女。", "Who is that girl with Grandma?", "和奶奶在一起的女孩是誰？", "She is her granddaughter.", "她是奶奶的孫女。"],
"grandfather": ["My grandfather likes to fish.", "我爺爺喜歡釣魚。", "Who tells you stories?", "誰跟你說故事？", "My grandfather tells me stories.", "我爺爺跟我說故事。"],
"grandmother": ["My grandmother makes dumplings.", "我奶奶會包水餃。", "Who cooks dinner on Sunday?", "星期天誰煮晚餐？", "My grandmother cooks dinner.", "我奶奶煮晚餐。"],
"grandson": ["Grandpa plays chess with his grandson.", "爺爺和他的孫子下棋。", "Who is that boy with Grandpa?", "和爺爺在一起的男孩是誰？", "He is his grandson.", "他是爺爺的孫子。"],
"grape": ["This grape is very sweet.", "這顆葡萄很甜。", "What fruit is purple?", "什麼水果是紫色的？", "The grape is purple.", "葡萄是紫色的。"],
"grass": ["The grass is green and soft.", "草地又綠又軟。", "Where do you sit in the park?", "你在公園坐在哪裡？", "I sit on the grass.", "我坐在草地上。"],
"gray": ["The sky is gray today.", "今天天空是灰色的。", "What color is your cat?", "你的貓是什麼顏色？", "My cat is gray.", "我的貓是灰色的。"],
"great": ["You did a great job!", "你做得很棒！", "How was your weekend?", "你的週末過得怎麼樣？", "It was really great.", "真的很棒。"],
"greedy": ["The greedy puppy ate all the food.", "那隻貪吃的小狗吃光了所有食物。", "Where did the cookies go?", "餅乾去哪裡了？", "Our greedy puppy ate them all.", "我們貪吃的小狗把它們全吃了。"],
"green": ["The grass is green in spring.", "春天草是綠色的。", "What color is your bag?", "你的書包是什麼顏色？", "My bag is green.", "我的書包是綠色的。"],
"greet": ["I greet my teacher every morning.", "我每天早上跟老師打招呼。", "What do you do when you see a teacher?", "你看到老師時會做什麼？", "I greet my teacher with a smile.", "我微笑著跟老師打招呼。"],
"ground": ["The leaves fall to the ground.", "葉子掉到地上。", "Where is your ball?", "你的球在哪裡？", "It is on the ground.", "在地上。"],
"group": ["We work in a group.", "我們分組合作。", "How do you do projects in class?", "你們在班上怎麼做專題？", "We work in a small group.", "我們以小組合作。"],
"grow": ["Plants grow in the sun.", "植物在陽光下生長。", "What do you plant in your garden?", "你在花園種什麼？", "I grow tomatoes and beans.", "我種番茄和豆子。"],
"growth": ["Water helps the growth of plants.", "水幫助植物生長。", "Why do you water the plants?", "你為什麼幫植物澆水？", "Water helps their growth.", "水幫助它們生長。"],
"guard": ["The guard stands at the gate.", "警衛站在大門口。", "Who opens the school gate?", "誰打開學校大門？", "The guard opens it.", "警衛打開它。"],
"guava": ["I like to eat guava.", "我喜歡吃芭樂。", "What fruit is green and crunchy?", "什麼水果是綠色又脆的？", "The guava is green and crunchy.", "芭樂是綠色又脆的。"],
"guess": ["Can you guess my age?", "你能猜猜我的年紀嗎？", "Do you know the answer?", "你知道答案嗎？", "No, but I can guess.", "不知道，但我可以猜。"],
"guest": ["We have a guest for dinner.", "我們晚餐有一位客人。", "Who is coming today?", "今天誰要來？", "A guest is coming for dinner.", "一位客人要來吃晚餐。"],
"guide": ["Our guide showed us the museum.", "我們的嚮導帶我們參觀博物館。", "Who showed you the museum?", "誰帶你們參觀博物館？", "Our guide showed us.", "我們的嚮導帶我們。"],
"guitar": ["My brother plays the guitar.", "我哥哥彈吉他。", "What instrument do you like?", "你喜歡什麼樂器？", "I like the guitar.", "我喜歡吉他。"],
"gun": ["The water gun is fun in summer.", "水槍在夏天很好玩。", "What toy do you play with in summer?", "你夏天玩什麼玩具？", "I play with a water gun.", "我玩水槍。"],
"guy": ["He is a nice guy.", "他是個不錯的傢伙。", "What is your new classmate like?", "你的新同學人怎麼樣？", "He is a nice guy.", "他是個不錯的人。"],
"gym": ["We play basketball in the gym.", "我們在體育館打籃球。", "Where do you have PE class?", "你們在哪裡上體育課？", "We have it in the gym.", "我們在體育館上。"],
