"note": ["I write a note in class.", "我在課堂上寫筆記。", "What do you do in class?", "你在課堂上做什麼？", "I take a note.", "我做筆記。"],
"notebook": ["I write in my notebook.", "我在筆記本上寫字。", "Where do you write your homework?", "你在哪裡寫功課？", "I write it in my notebook.", "我寫在筆記本上。"],
"nothing": ["There is nothing in the box.", "盒子裡什麼都沒有。", "What is in your bag?", "你的包包裡有什麼？", "There is nothing in it.", "裡面什麼都沒有。"],
"notice": ["I notice a new picture on the wall.", "我注意到牆上有一幅新的畫。", "Did you see the new sign?", "你有看到新的告示嗎？", "Yes, I notice it now.", "有，我現在注意到了。"],
"novel": ["I am reading a fun novel.", "我正在讀一本有趣的小說。", "What book do you like?", "你喜歡什麼書？", "I like this novel.", "我喜歡這本小說。"],
"November": ["It gets cool in November.", "十一月天氣變涼。", "When is your school trip?", "你的校外教學是什麼時候？", "It is in November.", "在十一月。"],
"now": ["I am doing my homework now.", "我現在在寫功課。", "When can we go to the park?", "我們什麼時候可以去公園？", "We can go now.", "我們現在就可以去。"],
"number": ["My lucky number is seven.", "我的幸運數字是七。", "What is your phone number?", "你的電話號碼是多少？", "I will write my number for you.", "我會把我的號碼寫給你。"],
"nurse": ["The nurse helps sick people.", "護理師幫助生病的人。", "Who works with the doctor?", "誰和醫生一起工作？", "The nurse works with him.", "護理師和他一起工作。"],
"obey": ["We obey the school rules.", "我們遵守學校規則。", "What do you do in class?", "你在課堂上做什麼？", "I obey my teacher.", "我聽從老師的話。"],
"object": ["What is that round object?", "那個圓形的物體是什麼？", "What is on the table?", "桌上有什麼？", "There is a small object on it.", "上面有一個小物體。"],
"occur": ["Typhoons often occur in summer.", "颱風常在夏天發生。", "When does it rain in Taiwan?", "台灣什麼時候下雨？", "Rain can occur any time.", "雨隨時都可能發生。"],
"ocean": ["Fish swim in the ocean.", "魚在海洋裡游泳。", "Where do whales live?", "鯨魚住在哪裡？", "They live in the ocean.", "牠們住在海洋裡。"],
"o'clock": ["I get up at seven o'clock.", "我七點起床。", "When does school start?", "學校幾點開始上課？", "It starts at eight o'clock.", "八點開始。"],
"October": ["It is cool in October.", "十月天氣很涼爽。", "When is your birthday?", "你的生日是什麼時候？", "My birthday is in October.", "我的生日在十月。"],
"of": ["I drink a cup of tea.", "我喝一杯茶。", "What do you want to drink?", "你想喝什麼？", "A glass of milk, please.", "請給我一杯牛奶。"],
"off": ["Please turn off the TV.", "請把電視關掉。", "What do you do before bed?", "你睡前做什麼？", "I turn off the light.", "我把燈關掉。"],
"offer": ["Can I offer you some tea?", "我可以請你喝點茶嗎？", "What do you do when a guest comes?", "有客人來時你會做什麼？", "I offer them some tea.", "我請他們喝茶。"],
"office": ["My dad works in an office.", "我爸爸在辦公室工作。", "Where is the teacher?", "老師在哪裡？", "She is in the office.", "她在辦公室裡。"],
"officer": ["The officer helps people.", "那位官員幫助人們。", "Who helped you find the way?", "誰幫你找到路？", "A police officer helped me.", "一位警官幫助我。"],
"official": ["The official gave a speech.", "那位官員發表了演講。", "Who came to our school today?", "今天誰來我們學校？", "A city official came.", "一位市政府官員來了。"],
"often": ["I often ride my bike.", "我常常騎腳踏車。", "Do you go to the library?", "你會去圖書館嗎？", "Yes, I often go there.", "會，我常常去那裡。"],
"oil": ["Mom cooks with a little oil.", "媽媽用一點點油煮菜。", "What do you put in the pan?", "你在平底鍋裡放什麼？", "I put in some oil.", "我放一些油。"],
"OK": ["Is it OK to sit here?", "我可以坐這裡嗎？", "How are you today?", "你今天好嗎？", "I am OK, thank you.", "我很好，謝謝你。"],
"old": ["My grandpa is old.", "我爺爺年紀大了。", "Is your bike new?", "你的腳踏車是新的嗎？", "No, it is old.", "不，它是舊的。"],
"omit": ["Do not omit your name on the test.", "考試時不要漏寫你的名字。", "Can I skip this part?", "我可以跳過這個部分嗎？", "Yes, you can omit it.", "可以，你可以省略它。"],
