"study": ["I study English every day.", "我每天學英文。", "What do you do after school?", "你放學後做什麼？", "I study at home.", "我在家讀書。"],
"stupid": ["Do not call anyone stupid.", "不要說任何人笨。", "What is a kind rule at school?", "學校有什麼友善的規則？", "Never call a friend stupid.", "絕對不要說朋友笨。"],
"style": ["I like her hair style.", "我喜歡她的髮型。", "What do you think of her new hair?", "你覺得她的新髮型怎麼樣？", "I love the style.", "我很喜歡這個風格。"],
"subject": ["My favorite subject is art.", "我最喜歡的科目是美術。", "What do you like to learn at school?", "你在學校喜歡學什麼？", "Math is my best subject.", "數學是我最好的科目。"],
"subway": ["We take the subway to the zoo.", "我們搭捷運去動物園。", "How do you go to the zoo?", "你怎麼去動物園？", "I take the subway.", "我搭捷運。"],
"succeed": ["If you practice, you will succeed.", "只要練習，你就會成功。", "What happens when you keep trying?", "一直努力會怎麼樣？", "I will succeed one day.", "我總有一天會成功。"],
"success": ["The school party was a big success.", "學校派對非常成功。", "How was the school party?", "學校派對怎麼樣？", "It was a big success!", "非常成功！"],
"successful": ["The science show was very successful.", "科學展非常成功。", "How was your class show?", "你們班的表演怎麼樣？", "It was very successful.", "非常成功。"],
"such": ["It is such a nice day!", "今天天氣真好！", "Do you like this park?", "你喜歡這個公園嗎？", "Yes, it is such a pretty park.", "喜歡，這個公園真漂亮。"],
"sudden": ["There was a sudden rain this afternoon.", "今天下午突然下雨。", "Why are your shoes wet?", "你的鞋子為什麼濕了？", "There was a sudden rain.", "突然下雨了。"],
"sugar": ["I put sugar in my tea.", "我在茶裡加糖。", "What makes the cake sweet?", "什麼讓蛋糕變甜？", "Sugar makes it sweet.", "糖讓它變甜。"],
"suggest": ["I suggest we go to the park.", "我建議我們去公園。", "Where should we go today?", "我們今天應該去哪裡？", "I suggest the library.", "我建議去圖書館。"],
"suit": ["My dad wears a suit to work.", "我爸爸穿西裝上班。", "What does your dad wear to work?", "你爸爸穿什麼上班？", "He wears a blue suit.", "他穿藍色西裝。"],
"summer": ["We swim in the summer.", "我們夏天去游泳。", "When is it very hot in Taiwan?", "台灣什麼時候很熱？", "It is very hot in summer.", "夏天很熱。"],
"sun": ["The sun is bright today.", "今天太陽很亮。", "What is in the sky in the day?", "白天天空中有什麼？", "The sun is in the sky.", "天空中有太陽。"],
"Sunday": ["I go to the park on Sunday.", "我星期天去公園。", "When do you see your grandma?", "你什麼時候去看奶奶？", "I see her on Sunday.", "我星期天去看她。"],
"sunny": ["It is sunny and warm today.", "今天陽光普照又溫暖。", "How is the weather this morning?", "今天早上天氣怎麼樣？", "It is sunny and nice.", "天氣晴朗又舒服。"],
"super": ["This is a super idea!", "這是個超棒的主意！", "How did I do on my drawing?", "我的畫畫得怎麼樣？", "You did a super job!", "你畫得超棒！"],
"supermarket": ["We buy food at the supermarket.", "我們在超市買食物。", "Where do you buy fruit?", "你在哪裡買水果？", "I buy fruit at the supermarket.", "我在超市買水果。"],
"supper": ["We eat supper at six.", "我們六點吃晚餐。", "What time do you eat at night?", "你晚上幾點吃飯？", "I eat supper at seven.", "我七點吃晚餐。"],
"supply": ["We keep a supply of water at home.", "我們在家裡存放一些水。", "What do you keep at home for typhoons?", "你家為颱風準備了什麼？", "We keep a supply of water.", "我們存放一些水。"],
"support": ["My family gives me support.", "我的家人支持我。", "Who helps you when you feel tired?", "你累的時候誰幫你？", "My mom gives me support.", "媽媽支持我。"],
"sure": ["I am sure I can do it.", "我確定我做得到。", "Can you help me with this box?", "你可以幫我搬這個箱子嗎？", "Sure, I can help.", "當然，我可以幫忙。"],
"surf": ["We watched the white surf at the beach.", "我們在海邊看白色的浪花。", "What did you see at the beach?", "你在海邊看到什麼？", "I saw the white surf.", "我看到白色的浪花。"],
"surface": ["The surface of the table is smooth.", "桌子的表面很光滑。", "How does the table feel?", "桌子摸起來怎麼樣？", "The surface feels smooth.", "表面摸起來很光滑。"],
"surprise": ["We made a surprise cake for Mom.", "我們為媽媽做了驚喜蛋糕。", "What did you give Mom on her birthday?", "你在媽媽生日時送她什麼？", "We gave her a surprise party.", "我們給她一個驚喜派對。"],
"survive": ["Cactus plants can survive with little water.", "仙人掌只需要一點水就能存活。", "Do plants need a lot of water?", "植物需要很多水嗎？", "Some plants survive with little water.", "有些植物只需要一點水就能存活。"],
